css:
/* ==========================================================================
   Crepuscular  -  a Marinara Engine starter theme by kolache
   The one structural idea: THE ALMANAC. Every chat is one continuous ruled
   ledger column (no bubbles, no gaps) with a double margin rule; each entry
   carries a moon-phase mark in the margin, keyed to its message number. The
   newest entry, Ctrl+K and dialogs are "observed": framed by registration
   crop marks, like a photographic plate. Home widgets are those plates.
   First glance: a night sea under an ordinary moon, hooded figures on a
   cliff, eyes at the edges of the page. Close look: the figures are having
   pancakes, the cat in the dark wears a crepe mask, the phases are bites,
   and the new moon in the margin is a black cat's two eyes.
   ========================================================================== */

:root {
  --mari-tokens-version: 1;

  /* ---- type ---- */
  --mari-font-ui: "Crimson Pro", "Iowan Old Style", Georgia, serif;
  --mari-font-heading: "IM Fell English SC", "Crimson Pro", Georgia, serif;
  --mari-font-chat: "Crimson Pro", "Iowan Old Style", Georgia, serif;
  --mari-chat-font-size: 1.125rem;
  --mari-chat-line-height: 1.6;
  --mari-paragraph-gap: 0.8em;
  --mari-dialogue-weight: 400;
  --mari-text-outline: 0;
  --mari-min-ui-text: 13px;

  /* ---- the almanac column ---- */
  --mari-chat-column: 47rem;
  --mari-message-measure: 68ch;
  --mari-msg-head-rule: none;
  --mari-chat-wash: none;
  --mari-chat-header-bg: none;
  --mari-pinned-speaker: on;
  --pc-margin: 2.75rem;            /* where the margin rule sits inside each entry */

  /* ---- shape: one shape language - square plates, round moons ---- */
  --radius: 2px;
  --mari-top-bar-plate-radius: 2px;
  --mari-home-widget-radius: 0px;
  --mari-home-widget-border-width: 1px;
  --mari-home-art: none;
  --mari-home-wash: transparent;
  --mari-home-hero-padding: 1.25rem 1.25rem 0.5rem;
  --mari-home-widget-title-font: "IM Fell English SC", Georgia, serif;
  --mari-home-widget-title-size: 1.5rem;
  --mari-home-widget-font: "Crimson Pro", Georgia, serif;
  --mari-home-widget-text-size: 1rem;
  --mari-home-widget-eyebrow-size: 0.75rem;
  --mari-home-widget-glow: transparent;
  --mari-professor-sprite-scale: 0.9;
  --mari-chat-row-art-opacity: 0;
  --mari-selected-tint: var(--primary);

  --mari-composer-placeholder: "Write your next entry...";

  /* ---- the backdrop: a sea, a moon, a cliff ---- */
  --mari-app-backdrop-size: cover;
  --mari-app-backdrop-position: 22% center;
  --mari-page-floor: color-mix(in srgb, var(--pc-sheet) 90%, transparent);  /* the world ghosts behind Library pages */

  /* ---- weather: the same sea, read through an almanac ---- */
  --mari-weather-amount: 0.8;
  --mari-weather-speed: 0.85;
  --mari-weather-tint-strength: 0.55;
  --mari-weather-rain-length: 1.6;
  --mari-weather-snow-image: url("theme:wx-sugar-0.png") url("theme:wx-sugar-1.png");
  --mari-weather-snow-size: 0.7;
  --mari-weather-leaf-image: url("theme:wx-scrap-0.png") url("theme:wx-scrap-1.png") url("theme:wx-scrap-2.png");
  --mari-weather-leaf-size: 1;
  --mari-weather-petal-image: url("theme:wx-scrap-1.png") url("theme:wx-scrap-2.png");
  --mari-weather-petal-size: 0.6;
  --mari-weather-dust-image: url("theme:wx-crumb-0.png") url("theme:wx-crumb-1.png");
  --mari-weather-dust-size: 0.6;
  --mari-weather-firefly-image: url("theme:wx-eyes.png");
  --mari-weather-firefly-size: 0.9;
  --mari-weather-lightning-bolt: 0.9;   /* thin, branched: an engraved bolt, not a cartoon zigzag */
  --mari-weather-moon: none;      /* the backdrop paints its own moon */
}

/* ===================== NIGHT: the sea under the watcher ===================== */
:root[data-theme="dark"] {
  --pc-ink: #e9e1cc;
  --pc-sheet: #10141e;
  --pc-sheet-2: #151a26;
  --pc-rule: #3a3f4f;
  --pc-rule-gold: rgba(226, 196, 135, 0.42);
  --pc-gold: #e2c487;
  --pc-muted: #aaa392;

  --background: #090c13;
  --foreground: var(--pc-ink);
  --card: #10141e;
  --card-foreground: var(--pc-ink);
  --popover: #121723;
  --popover-foreground: var(--pc-ink);
  --primary: #e2c487;
  --primary-foreground: #1b1508;
  --secondary: #1a1f2c;
  --secondary-foreground: var(--pc-ink);
  --muted: #171c28;
  --muted-foreground: var(--pc-muted);
  --accent: #1d2331;
  --accent-foreground: var(--pc-ink);
  --destructive: #c4574a;
  --destructive-foreground: #fff4ee;
  --border: #2b3040;
  --input: #2b3040;
  --ring: #e2c487;
  --sidebar: #0b0e16;
  --sidebar-foreground: var(--pc-ink);
  --sidebar-border: #262b39;
  --sidebar-accent: #161b27;
  --sidebar-accent-foreground: var(--pc-ink);

  --ov-line: #262b39;
  --ov-text: var(--pc-ink);
  --ov-muted: var(--pc-muted);
  --ov-dim: #858072;
  --ov-accent: #e2c487;
  --ov-hover: rgba(226, 196, 135, 0.07);
  --ov-active-bg: rgba(226, 196, 135, 0.12);
  --mari-accent-text: #e9cf98;
  --mari-chrome-accent: #e2c487;
  --mari-chrome-muted: var(--pc-muted);
  --mari-mode-conversation: #9fc0c4;
  --mari-mode-roleplay: #e2c487;
  --mari-mode-game: #c99ac0;
  --ov-mode-conversation: #9fc0c4;
  --ov-mode-roleplay: #e2c487;
  --ov-mode-game: #c99ac0;
  --mari-home-pink: #d79a9a;
  --mari-home-violet: #a9a2d6;
  --mari-dialogue-color: #ecd6a6;
  --mari-weather-strength: 1.15;
  --mari-message-time: #8f8a7c;
  --mari-message-actions: #a49e8d;
  --mari-swipe-counter: #a49e8d;
  --mari-scrim: rgba(4, 6, 10, 0.72);
  --mari-confirm-scrim: rgba(4, 6, 10, 0.35);

  --mari-app-backdrop: url("theme:world-night.webp");
  --mari-top-bar-bg: #070910;
  --mari-top-bar-plate: rgba(9, 12, 19, 0.9);
  --mari-top-bar-plate-active: #231f17;
  --mari-home-widget-bg: rgba(16, 20, 30, 0.84);  /* the moon ghosts through the plate */
  --mari-home-widget-border: #2b3040;
  --mari-home-widget-title-color: #efe4c6;
  --mari-home-widget-eyebrow-color: #e2c487;
  --mari-home-widget-muted: var(--pc-muted);
  --mari-focus-frame: url("theme:crop-night.svg") 24 / 14px stretch;
  --mari-focus-frame-outset: 7px;
  --mari-stage-empty-bg: url("theme:world-night.webp") 22% center / cover, #090c13;
  --mari-user-avatar-placeholder: radial-gradient(circle at 40% 35%, #f6e7c0, #c79a55);

  --mari-weather-rain-color: #9fb3c8;
  --mari-weather-snow-color: #fff8e6;
  --mari-weather-fog-color: #8a93a6;
  --mari-weather-star-color: #efe2bd;
  --mari-weather-lightning-color: #2a3d63;   /* deep blue: the app fills the flash in this colour (max 60%), so the sky stays dark; the bolt core is always white */
}

/* ===================== DAY: a foggy breakfast by the sea ===================== */
:root[data-theme="light"] {
  --pc-ink: #221f19;
  --pc-sheet: #f4efe3;
  --pc-sheet-2: #ece5d4;
  --pc-rule: #cdbf9f;
  --pc-rule-gold: rgba(122, 78, 23, 0.4);
  --pc-gold: #7a4e17;
  --pc-muted: #5e5544;

  --background: #e6e3da;
  --foreground: var(--pc-ink);
  --card: #f4efe3;
  --card-foreground: var(--pc-ink);
  --popover: #f6f2e8;
  --popover-foreground: var(--pc-ink);
  --primary: #7a4e17;
  --primary-foreground: #fff8ea;
  --secondary: #e9e2d0;
  --secondary-foreground: var(--pc-ink);
  --muted: #ebe5d6;
  --muted-foreground: var(--pc-muted);
  --accent: #e6dcc6;
  --accent-foreground: var(--pc-ink);
  --destructive: #a33a2c;
  --destructive-foreground: #fff7f2;
  --border: #d3c7ac;
  --input: #cdbf9f;
  --ring: #7a4e17;
  --sidebar: #efeadf;
  --sidebar-foreground: var(--pc-ink);
  --sidebar-border: #d3c7ac;
  --sidebar-accent: #e6dfcd;
  --sidebar-accent-foreground: var(--pc-ink);

  --ov-line: #d3c7ac;
  --ov-text: var(--pc-ink);
  --ov-muted: var(--pc-muted);
  --ov-dim: #6f6654;
  --ov-accent: #7a4e17;
  --ov-hover: rgba(122, 78, 23, 0.07);
  --ov-active-bg: rgba(122, 78, 23, 0.12);
  --mari-accent-text: #6e4614;
  --mari-chrome-accent: #7a4e17;
  --mari-chrome-muted: var(--pc-muted);
  --mari-mode-conversation: #2f6468;
  --mari-mode-roleplay: #7a4e17;
  --mari-mode-game: #7d3f72;
  --ov-mode-conversation: #2f6468;
  --ov-mode-roleplay: #7a4e17;
  --ov-mode-game: #7d3f72;
  --mari-home-pink: #9c4747;
  --mari-home-violet: #554d94;
  --mari-dialogue-color: #6b3f10;
  --mari-message-time: #6f6654;
  --mari-message-actions: #6b6252;
  --mari-swipe-counter: #6b6252;
  --mari-scrim: rgba(60, 56, 48, 0.45);
  --mari-confirm-scrim: rgba(60, 56, 48, 0.18);

  --mari-app-backdrop: url("theme:world-day.webp");
  --mari-top-bar-bg: #d9dbd5;
  --mari-top-bar-plate: rgba(244, 239, 227, 0.92);
  --mari-top-bar-plate-active: #e8dcc2;
  --mari-home-widget-bg: rgba(244, 239, 227, 0.8);   /* the fogged sky ghosts through */
  --mari-home-widget-border: #d3c7ac;
  --mari-home-widget-title-color: #221f19;
  --mari-home-widget-eyebrow-color: #7a4e17;
  --mari-home-widget-muted: var(--pc-muted);
  --mari-focus-frame: url("theme:crop-day.svg") 24 / 14px stretch;
  --mari-focus-frame-outset: 7px;
  --mari-stage-empty-bg: url("theme:world-day.webp") 22% center / cover, #e6e3da;
  --mari-user-avatar-placeholder: radial-gradient(circle at 40% 35%, #f6e7c0, #c79a55);

  --mari-weather-rain-color: #55646f;
  --mari-weather-snow-color: #fffaf0;
  --mari-weather-snow-image: url("theme:wx-sugar-day-0.png") url("theme:wx-sugar-day-1.png");  /* a warm dark edge reads on fog */
  --mari-weather-snow-size: 0.9;
  --mari-weather-fog-color: #b9b2a2;
  --mari-weather-strength: 1.25;
  --mari-weather-star-color: #8a6a3a;
  --mari-weather-lightning-color: #d9ccb0;
}

/* ---- round 6 (owner): the backdrop is the batch-2 painting as painted, whole: the sea, the cliff with the
   hooded cult at breakfast, and its own small moon with a faint cat-head ghost in the sky. Nothing is added
   or enlarged; each screen size only chooses which part of the picture sits where (cult first). ---- */
:root {
  --pc-world-pos: 22% center;
  --pc-world-size: cover;
  --pc-world-layers: var(--pc-world) var(--pc-world-pos) / var(--pc-world-size) no-repeat, var(--pc-world) 22% center / cover no-repeat, var(--background);
  --pc-sky-layers: var(--pc-world-layers);
  --mari-app-backdrop-layers: var(--pc-sky-layers);
  --mari-weather-sun: none;   /* one celestial body only: the painting's own moon */
}
:root[data-theme="dark"] { --pc-world: url("theme:world-night.webp"); }
:root[data-theme="light"] { --pc-world: url("theme:world-day.webp"); }

/* Home on a desktop: from 1701px the whole picture is in view (moon top left, cult right of the plates) */
:root:not([data-chat-id]) {
  --pc-world-pos: 100% center;
}
/* tablet landscape Home: the cult stands at the right of the main area, in the gaps between the plates */
@media (min-width: 761px) and (max-width: 1279px) {
  :root:not([data-chat-id]) { --pc-world-pos: calc(100vw - 1687px) center; }
}
/* the framed sky beside Recent (two-column Home, 1280-1599) holds the cult. Round 6b: the picture is at its
   native size (1:1 with the painting's pixels, never soft) and raised 125px, so the table, teapot and the
   pancake stack (x 1437, y 618 in the painting) sit above the window's graticule foot, about 150px in from
   its right edge, the hooded heads staring up. On screens taller than the raised picture its foot fades into
   the page colour (under the bottom plates), so no seam shows. The right edge stays under the opaque sidebar. */
@media (min-width: 1280px) and (max-width: 1599px) {
  :root:not([data-chat-id]) {
    --pc-world-size: auto 941px;
    --pc-world-pos: calc(100vw - 1921px) -125px;
    --pc-sky-layers: linear-gradient(to bottom, transparent 770px, var(--background) 816px), var(--pc-world-layers);
  }
}
/* three-column Home (1600-1700): the window is the middle column (foot at about 680px); same native size */
@media (min-width: 1600px) and (max-width: 1700px) {
  :root:not([data-chat-id]) {
    --pc-world-size: auto 941px;
    --pc-world-pos: calc(50vw - 1506px) -15px;
    --pc-sky-layers: linear-gradient(to bottom, transparent 880px, var(--background) 926px), var(--pc-world-layers);
  }
}
/* a chat on a desktop: native scale, slid so the hooded figures stand in the right-hand gutter; from about
   1660px the painted moon comes into the left gutter as well (from 1701px the cover picture holds both) */
@media (min-width: 1100px) and (max-width: 1700px) {
  :root[data-chat-id] {
    --pc-world-size: auto max(941px, 100vh);
    --pc-world-pos: calc(100vw - 1765px) center;
    --pc-storm-size: var(--pc-world-size);  /* the vigil goes on in bad weather (lantern under umbrellas) */
    --pc-storm-pos: var(--pc-world-pos);
  }
}

/* bad weather greys the same sea over (no separate moon: the storm hides it) */
:root[data-theme="light"][data-mari-weather="rain"],
:root[data-theme="light"][data-mari-weather="storm"],
:root[data-theme="light"][data-mari-weather="hail"] {
  --mari-app-backdrop: url("theme:bg-day-rain.webp");
  --pc-sky-layers: url("theme:bg-day-rain.webp") var(--pc-storm-pos, var(--mari-app-backdrop-position)) / var(--pc-storm-size, cover) no-repeat, url("theme:bg-day-rain.webp") var(--mari-app-backdrop-position) / cover no-repeat, var(--background);
}
:root[data-theme="dark"][data-mari-weather="rain"],
:root[data-theme="dark"][data-mari-weather="storm"],
:root[data-theme="dark"][data-mari-weather="hail"] {
  --mari-app-backdrop: url("theme:bg-night-storm.webp");
  --pc-sky-layers: url("theme:bg-night-storm.webp") var(--pc-storm-pos, var(--mari-app-backdrop-position)) / var(--pc-storm-size, cover) no-repeat, url("theme:bg-night-storm.webp") var(--mari-app-backdrop-position) / cover no-repeat, var(--background);
}

/* phones (and a tablet held upright) get the portrait painting: moon top right, cult at the foot */
@media (max-width: 760px), (max-width: 1023px) and (orientation: portrait) {
  :root[data-theme="dark"] { --pc-world: url("theme:world-phone-night.webp"); }
  :root[data-theme="light"] { --pc-world: url("theme:world-phone-day.webp"); }
  :root, :root:not([data-chat-id]), :root[data-chat-id] {
    --mari-app-backdrop-position: center top;
    --pc-world-pos: center top;
    --pc-world-size: cover;
  }
  /* a tablet held upright: Home keeps the top (the moon right of the greeting), a chat shows the foot of
     the picture, where the cult sits on its cliff beside the column */
  :root[data-chat-id] { --pc-world-pos: center bottom; }
}
/* a tablet held upright, Home: the portrait picture is drawn at twice the phone's scale here, so its moon
   would read as a big face; the picture rises until the moon (and its ghost's ears) are wholly behind the
   top bar */
@media (min-width: 600px) and (max-width: 1023px) and (orientation: portrait) {
  :root:not([data-chat-id]) { --pc-world-pos: center -330px; }
}
/* a phone: the whole portrait picture at its cover scale, held low so the cult always sits at the screen's
   foot (in a browser with its toolbars too); on a full-height screen the painted moon peeks out beside the
   greeting plate */
@media (max-width: 760px) {
  :root, :root:not([data-chat-id]), :root[data-chat-id] {
    --pc-world-size: cover;
    --pc-world-pos: center 85%;
  }
}
@media (max-width: 760px) {
  :root { --pc-margin: 2.1rem; }
  :root[data-theme="light"][data-mari-weather="rain"],
  :root[data-theme="light"][data-mari-weather="storm"],
  :root[data-theme="light"][data-mari-weather="hail"] { --mari-app-backdrop-position: 95% center; }  /* the cult under its umbrellas */
  :root[data-theme="dark"][data-mari-weather="rain"],
  :root[data-theme="dark"][data-mari-weather="storm"],
  :root[data-theme="dark"][data-mari-weather="hail"] { --mari-app-backdrop-position: 95% center; }  /* the cult under its one big umbrella, with the lantern */
}

/* indoors (the app says so from the story location): the same sea and moon, seen through a leaded window */
:root[data-theme="dark"] { --pc-window: url("theme:window-night.svg"); }
:root[data-theme="light"] { --pc-window: url("theme:window-day.svg"); }
:root[data-mari-shelter="indoors"] {
  --mari-app-backdrop-layers: var(--pc-window) center / 100% 100% no-repeat, var(--pc-sky-layers);
}

/* ============================ TOP BAR ============================ */
[data-mari-part="top-bar"] {
  border-bottom: 1px solid var(--pc-rule-gold);
}
[data-mari-part="top-bar"] .ov-tab__label {
  font-family: var(--mari-font-ui);
  font-size: 0.95rem;
  letter-spacing: 0.01em;
}

/* ============================ THE ALMANAC COLUMN ============================ */
/* rows touch, so the entries form one continuous ruled sheet */
[data-chat-mode="roleplay"] [data-mari-part="message"] {
  margin-bottom: 0;
}

/* the sheet is painted on the message body (bubble + its tool strip), so entries join up */
[data-chat-mode="roleplay"] [data-mari-part="message"] {
  padding-bottom: 0;
}
[data-chat-mode="roleplay"] [data-mari-part="message"] > .mari-message-body {
  border-left: 1px solid var(--pc-rule);
  border-right: 1px solid var(--pc-rule);
  background:
    linear-gradient(to right, transparent calc(var(--pc-margin) - 4px), var(--pc-rule-gold) calc(var(--pc-margin) - 4px),
      var(--pc-rule-gold) calc(var(--pc-margin) - 3px), transparent calc(var(--pc-margin) - 3px),
      transparent var(--pc-margin), var(--pc-rule-gold) var(--pc-margin), var(--pc-rule-gold) calc(var(--pc-margin) + 1px),
      transparent calc(var(--pc-margin) + 1px)),
    var(--pc-sheet);
  background-color: var(--pc-sheet);
  position: relative;
}
[data-chat-mode="roleplay"] [data-mari-part="message"] > .mari-message-body {
  background-image:
    url("theme:grat-night.svg"),
    linear-gradient(to right, transparent calc(var(--pc-margin) - 4px), var(--pc-rule-gold) calc(var(--pc-margin) - 4px),
      var(--pc-rule-gold) calc(var(--pc-margin) - 3px), transparent calc(var(--pc-margin) - 3px),
      transparent var(--pc-margin), var(--pc-rule-gold) var(--pc-margin), var(--pc-rule-gold) calc(var(--pc-margin) + 1px),
      transparent calc(var(--pc-margin) + 1px));
  background-size: 48px 7px, auto;
  background-repeat: repeat-x, no-repeat;
  background-position: 0 0, 0 0;
}
:root[data-theme="light"] [data-chat-mode="roleplay"] [data-mari-part="message"] > .mari-message-body {
  background-image:
    url("theme:grat-day.svg"),
    linear-gradient(to right, transparent calc(var(--pc-margin) - 4px), var(--pc-rule-gold) calc(var(--pc-margin) - 4px),
      var(--pc-rule-gold) calc(var(--pc-margin) - 3px), transparent calc(var(--pc-margin) - 3px),
      transparent var(--pc-margin), var(--pc-rule-gold) var(--pc-margin), var(--pc-rule-gold) calc(var(--pc-margin) + 1px),
      transparent calc(var(--pc-margin) + 1px));
}
/* the sheet runs on below the newest entry, down under the composer: no band of sea */
[data-chat-mode="roleplay"] [data-mari-part="message"][data-latest] > .mari-message-body::after {
  content: "";
  position: absolute;
  top: 100%;
  left: -1px;
  right: -1px;
  height: 4.5rem;
  border-inline: 1px solid var(--pc-rule);
  background:
    linear-gradient(to right, transparent calc(var(--pc-margin) - 4px), var(--pc-rule-gold) calc(var(--pc-margin) - 4px),
      var(--pc-rule-gold) calc(var(--pc-margin) - 3px), transparent calc(var(--pc-margin) - 3px),
      transparent var(--pc-margin), var(--pc-rule-gold) var(--pc-margin), var(--pc-rule-gold) calc(var(--pc-margin) + 1px),
      transparent calc(var(--pc-margin) + 1px)),
    var(--pc-sheet);
  pointer-events: none;
}
/* the regenerate / swipe strip sits inside the entry's foot, on the sheet */
[data-chat-mode="roleplay"] [data-mari-part="message"][data-message-role="assistant"] > .mari-message-body {
  padding-bottom: 1.8rem;
}
[data-chat-mode="roleplay"] [data-mari-part="message"] > .mari-message-body > [data-mari-part="actions"] {
  top: auto;
  bottom: 0.1rem;
}
[data-chat-mode="roleplay"] [data-mari-part="message"][data-message-role="user"] > .mari-message-body {
  background-color: var(--pc-sheet-2);
}
[data-chat-mode="roleplay"] [data-mari-part="message"][data-message-role="user"] [data-mari-part="header"][data-placement="outside"] {
  --pc-head-sheet: var(--pc-sheet-2);
}
:root[data-theme="dark"] { --pc-grat: url("theme:grat-night.svg"); }
:root[data-theme="light"] { --pc-grat: url("theme:grat-day.svg"); }

[data-mari-part="bubble"].mari-rp-bubble {
  width: 100%;
  max-width: none;
  align-self: stretch;
  border-radius: 0;
  border: 0;
  box-shadow: none;
  background: transparent;
  color: var(--pc-ink);
  position: relative;
}
[data-mari-part="bubble"].mari-rp-bubble > div {
  padding-left: calc(var(--pc-margin) + 0.9rem);
  padding-right: 1.1rem;
  padding-top: 0.85rem;
}

/* the margin mark: moon phase by message number; your entries get a paw */
[data-mari-part="bubble"].mari-rp-bubble::before {
  content: "";
  position: absolute;
  left: calc((var(--pc-margin) - 4px - 1.45rem) / 2);
  top: 0.9rem;
  width: 1.45rem;
  height: 1.45rem;
  background: url("theme:phase-0.svg") center / contain no-repeat;
  pointer-events: none;
}
[data-mari-part="message"][data-message-index$="1"] [data-mari-part="bubble"]::before { background-image: url("theme:phase-1.svg"); }
[data-mari-part="message"][data-message-index$="2"] [data-mari-part="bubble"]::before { background-image: url("theme:phase-2.svg"); }
[data-mari-part="message"][data-message-index$="3"] [data-mari-part="bubble"]::before { background-image: url("theme:phase-3.svg"); }
[data-mari-part="message"][data-message-index$="4"] [data-mari-part="bubble"]::before { background-image: url("theme:phase-4.svg"); }
[data-mari-part="message"][data-message-index$="5"] [data-mari-part="bubble"]::before { background-image: url("theme:phase-5.svg"); }
[data-mari-part="message"][data-message-index$="6"] [data-mari-part="bubble"]::before { background-image: url("theme:phase-6.svg"); }
[data-mari-part="message"][data-message-index$="7"] [data-mari-part="bubble"]::before { background-image: url("theme:phase-7.svg"); }
[data-mari-part="message"][data-message-index$="8"] [data-mari-part="bubble"]::before { background-image: url("theme:phase-8.svg"); }
[data-mari-part="message"][data-message-index$="9"] [data-mari-part="bubble"]::before { background-image: url("theme:phase-9.svg"); }
[data-mari-part="message"][data-message-role="user"] [data-mari-part="bubble"].mari-rp-bubble::before {
  background-image: url("theme:paw-night.svg");
  width: 1.1rem;
  height: 1.1rem;
  left: calc((var(--pc-margin) - 4px - 1.1rem) / 2);
  top: 1.05rem;
  opacity: 0.85;
}
:root[data-theme="light"] [data-mari-part="message"][data-message-role="user"] [data-mari-part="bubble"].mari-rp-bubble::before {
  background-image: url("theme:paw-day.svg");
}

/* entry heading: the speaker in small caps, like an almanac entry */
[data-mari-part="bubble"] [data-mari-part="header"] .mari-message-name {
  font-family: var(--mari-font-heading);
  font-size: 1.05rem;
  font-weight: 400;
  letter-spacing: 0.02em;
  color: var(--pc-gold);
}
:root[data-theme="light"] [data-mari-part="bubble"] [data-mari-part="header"] .mari-message-name {
  color: #6e4614;
}
[data-mari-part="time"] {
  font-size: 0.75rem;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.04em;
}

/* avatars: small moons seated in the margin, above the phase mark (yours too: every entry starts on the left) */
[data-chat-mode="roleplay"] .mari-roleplay-message-row.mari-message-user {
  flex-direction: row !important;
}
[data-chat-mode="roleplay"] .mari-roleplay-message-row {
  column-gap: 0.75rem !important;
}
[data-chat-mode="roleplay"] .mari-roleplay-message-row > [data-mari-part="avatar"] {
  order: -1;
  margin: 0 !important;
  position: relative;
  z-index: 2;
  /* across the gap, onto the sheet, centred in the margin (left of the double rule) */
  grid-column: 2 !important;
  grid-row: 1 !important;
  /* from the centre of its 2.5rem gutter column, across the gap, onto the sheet, centred left of the double rule */
  transform: translateX(calc(2.5rem - (2.5rem - 1.75rem) / 2 + 0.75rem + 1px + (var(--pc-margin) - 4px - 1.75rem) / 2));
  padding-top: 0.5rem;
}
[data-chat-mode="roleplay"] .mari-roleplay-message-row > .mari-message-body { order: 0; grid-column: 3 !important; grid-row: 1 !important; }
[data-chat-mode="roleplay"] .mari-roleplay-message-row > [data-mari-part="avatar"] button {
  width: 1.75rem !important;
  height: 1.75rem !important;
}
[data-chat-mode="roleplay"] [data-mari-part="avatar"] button {
  border-radius: 999px;
  box-shadow: 0 0 0 1px var(--pc-rule-gold);
  --tw-ring-color: transparent;
}
@media (min-width: 761px) {
  [data-chat-mode="roleplay"] [data-mari-part="bubble"].mari-rp-bubble::before { top: 2.65rem; }
  [data-chat-mode="roleplay"] [data-mari-part="message"][data-message-role="user"] [data-mari-part="bubble"].mari-rp-bubble::before { top: 2.8rem; }
  [data-chat-mode="roleplay"] [data-mari-part="header"][data-placement="outside"] ~ [data-mari-part="bubble"].mari-rp-bubble::before { top: 1.1rem; }
}
[data-chat-mode="roleplay"] .rpg-avatar-glow {
  filter: none;
  box-shadow: none;
}

/* ============================ CONVERSATION ============================ */
/* the same ledger, full width: avatars sit in the margin, lines run right of the double rule */
[data-chat-mode="conversation"] .mari-messages-scroll {
  --pc-margin: 4.25rem;
  background:
    linear-gradient(to right, transparent calc(var(--pc-margin) - 4px), var(--pc-rule-gold) calc(var(--pc-margin) - 4px),
      var(--pc-rule-gold) calc(var(--pc-margin) - 3px), transparent calc(var(--pc-margin) - 3px),
      transparent var(--pc-margin), var(--pc-rule-gold) var(--pc-margin), var(--pc-rule-gold) calc(var(--pc-margin) + 1px),
      transparent calc(var(--pc-margin) + 1px)),
    var(--pc-sheet);
}
/* below 768px the app stacks the avatar above the text, so lines start 17px in: the margin rule moves to
   the sheet's edge, clear of every name and line */
@media (max-width: 767px) {
  [data-chat-mode="conversation"] .mari-messages-scroll,
  [data-chat-mode="conversation"] .ov-typing,
  [data-chat-mode="conversation"] [data-mari-part="composer"] { --pc-margin: 0.6rem !important; }
}
/* the app's "observed message" crop marks sit 7px outside a full-width conversation row, i.e. outside the
   sheet: the conversation ledger marks entries with the graticule alone */
[data-chat-mode="conversation"] [data-mari-part="message"] {
  border-image: none !important;
}
/* the contact plate pinned at the top of the conversation is solid, so the margin rule passes behind it */
[data-chat-mode="conversation"] .mari-messages-scroll > .sticky .pointer-events-auto,
[data-chat-mode="conversation"] .mari-messages-scroll > .sticky .marinara-chat-toolbar-button {
  background-color: var(--pc-sheet-2, var(--pc-sheet)) !important;
}
/* round 7: these plates are opaque, so the app's 12px backdrop blur behind them shows nothing, yet over the
   painted backdrop WebKit re-blurs it every frame while a chat settles (iPad Air: ~8s of slow frames) */
[data-chat-mode="conversation"] .mari-messages-scroll > .sticky .pointer-events-auto,
[data-chat-mode="conversation"] .mari-messages-scroll > .sticky .marinara-chat-toolbar-button,
[data-mari-part="composer"] .mari-chat-input-box {
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
}
/* the sheet runs on under the typing row and the composer to the screen's foot (no band of sea between) */
[data-chat-mode="conversation"] .ov-typing,
[data-chat-mode="conversation"] [data-mari-part="composer"] {
  --pc-margin: 4.25rem;
  background:
    linear-gradient(to right, transparent calc(var(--pc-margin) - 4px), var(--pc-rule-gold) calc(var(--pc-margin) - 4px),
      var(--pc-rule-gold) calc(var(--pc-margin) - 3px), transparent calc(var(--pc-margin) - 3px),
      transparent var(--pc-margin), var(--pc-rule-gold) var(--pc-margin), var(--pc-rule-gold) calc(var(--pc-margin) + 1px),
      transparent calc(var(--pc-margin) + 1px)),
    var(--pc-sheet);
}
[data-chat-mode="conversation"] [data-mari-part="message"] + [data-mari-part="message"] > .mari-message {
  background: url("theme:grat-night.svg") var(--pc-margin) 0 / 48px 7px repeat-x;
}
:root[data-theme="light"] [data-chat-mode="conversation"] [data-mari-part="message"] + [data-mari-part="message"] > .mari-message {
  background-image: url("theme:grat-day.svg");
}
[data-chat-mode="conversation"] [data-mari-part="header"] .mari-message-name,
[data-chat-mode="conversation"] [data-mari-part="header"] > :first-child {
  font-family: var(--mari-font-heading);
  font-weight: 400;
  color: var(--pc-gold);
}
[data-mari-part="chat-header"] > * {
  background: var(--pc-sheet-2);
  border: 1px solid var(--pc-rule);
  border-radius: 2px;
}
[data-chat-mode="conversation"] [data-mari-part="avatar"] button {
  border-radius: 999px;
}

/* phones: the name line sits above the entry; it joins the sheet */
[data-chat-mode="roleplay"] [data-mari-part="header"][data-placement="outside"] {
  /* the name line stands on the sheet (so text scrolling under the pinned line is hidden), but only right of the
     margin rule: the margin column, with the avatar moon in it, stays open; the entry's tick rule runs along its head */
  background:
    var(--pc-grat) 0 0 / 48px 7px repeat-x,
    linear-gradient(to right, transparent calc(var(--pc-margin) + 1px), var(--pc-head-sheet, var(--pc-sheet)) calc(var(--pc-margin) + 1px));
  border: 0;
  border-radius: 0;
  justify-content: flex-start;
  flex-direction: row;
  align-self: stretch;
  padding: 0.5rem 0.5rem 0 calc(var(--pc-margin) + 0.9rem);
}
[data-chat-mode="roleplay"] [data-mari-part="header"][data-placement="outside"] > * {
  margin-left: 0 !important;
  margin-right: 0 !important;
  order: 0 !important;
}
[data-chat-mode="roleplay"] [data-mari-part="header"][data-placement="outside"] .mari-message-name {
  font-family: var(--mari-font-heading);
  font-weight: 400;
  font-size: 1rem;
  color: var(--pc-gold);
}

/* ============================ COMPOSER ============================ */
[data-chat-mode="roleplay"] [data-mari-part="composer"] {
  /* the double margin rule carries on down through the composer's frame */
  background:
    linear-gradient(to right, transparent calc(var(--pc-margin) - 4px), var(--pc-rule-gold) calc(var(--pc-margin) - 4px),
      var(--pc-rule-gold) calc(var(--pc-margin) - 3px), transparent calc(var(--pc-margin) - 3px),
      transparent var(--pc-margin), var(--pc-rule-gold) var(--pc-margin), var(--pc-rule-gold) calc(var(--pc-margin) + 1px),
      transparent calc(var(--pc-margin) + 1px)),
    var(--pc-sheet);
  box-shadow: -1px 0 0 var(--pc-rule), 1px 0 0 var(--pc-rule);
}
/* below the width where the ledger reaches its full measure, the app's composer column spans the avatar
   columns too; inset it to the sheet so the foot of the ledger keeps one width (tablets, small laptops) */
@media (min-width: 761px) and (max-width: 1279px) {
  [data-chat-mode="roleplay"] .mari-roleplay-input-column {
    padding-inline: calc(1.5vw + 68.5px) !important;
  }
}
@media (min-width: 1280px) and (max-width: 1439px) {
  [data-chat-mode="roleplay"] .mari-roleplay-input-column {
    padding-inline: max(0px, calc((1395px - 100vw) / 2)) !important;
  }
}
/* the end of the sheet: a plate with a gold double rule on top */
[data-mari-part="composer"] .mari-chat-input-box {
  border-radius: 0 !important;
  border: 1px solid var(--pc-rule);
  border-top-color: var(--pc-rule-gold);
  /* second gold rule painted inside, so the box keeps the stock 1px border height */
  background: linear-gradient(var(--pc-rule-gold), var(--pc-rule-gold)) 0 2px / 100% 1px no-repeat, var(--pc-sheet);
  box-shadow: none;
}
[data-mari-part="composer"] textarea {
  font-family: var(--mari-font-chat);
  font-size: 1.05rem;
  color: var(--pc-ink);
}
/* phone: keep the stock line box (1.25rem) so the larger chat face adds no height to the composer */
@media (max-width: 767px) {
  [data-mari-part="composer"] textarea { line-height: 1.25rem; }
}
[data-mari-part="composer"] button {
  border-radius: 2px;
}
[data-mari-part="composer"] .mari-chat-send-btn {
  background: var(--primary);
  color: var(--primary-foreground);
}

/* where the gutter is narrow (tablets, small laptops) a smaller creature leans in from the right-hand edge,
   inside the gutter beside the ledger, so it never sits over the text */
@media (min-width: 1280px) and (max-width: 1379px) {
  [data-chat-mode="roleplay"]::after {
    content: "";
    position: absolute;
    right: 0;
    bottom: 7rem;
    width: 2.2rem;
    height: 3.7rem;
    background: url("theme:creature-peek.webp") right bottom / contain no-repeat;
    pointer-events: none;
  }
  :root[data-theme="light"] [data-chat-mode="roleplay"]::after { background-image: url("theme:creature-peek-day.webp"); }
}

/* the creature leans out from behind the sidebar, in the gutter beside the column (wide screens only) */
@media (min-width: 1380px) {
  [data-chat-mode="roleplay"]::after {
    content: "";
    position: absolute;
    right: 0;
    bottom: 1rem;
    width: 5.4rem;
    height: 9rem;
    background: url("theme:creature-peek.webp") right bottom / contain no-repeat;
    pointer-events: none;
  }
  :root[data-theme="light"] [data-chat-mode="roleplay"]::after { background-image: url("theme:creature-peek-day.webp"); }
}

/* ============================ GAME: the narration is the almanac's current entry ============================ */
[data-mari-part="message"][data-game-narration] {
  border-radius: 0 !important;
  border: 1px solid var(--pc-rule);
  border-top: 3px double var(--pc-rule-gold);
  background:
    linear-gradient(to right, transparent 0.45rem, var(--pc-rule-gold) 0.45rem, var(--pc-rule-gold) calc(0.45rem + 1px), transparent calc(0.45rem + 1px)),
    var(--pc-sheet);
  box-shadow: none;
}
[data-mari-part="message"][data-game-narration] * {
  border-radius: 2px;
}
[data-mari-part="message"][data-game-narration] [data-mari-part="header"] {
  font-family: var(--mari-font-heading);
  letter-spacing: 0.06em;
}
[data-mari-part="game-hud"] {
  border-radius: 0;
}
/* the map float is a sea chart: deep water ruled with a faint star-chart graticule (a real map draws over it) */
[data-mari-part="game-hud"] [data-tour="game-map"] {
  border-radius: 0 !important;
  border-color: var(--pc-rule-gold) !important;
  background:
    repeating-linear-gradient(90deg, rgba(226, 196, 135, 0.13) 0 1px, transparent 1px 18px),
    repeating-linear-gradient(0deg, rgba(226, 196, 135, 0.13) 0 1px, transparent 1px 18px),
    radial-gradient(ellipse at 30% 40%, #13213a, #070b14 80%) !important;
}
:root[data-theme="light"] [data-mari-part="game-hud"] [data-tour="game-map"] {
  background:
    repeating-linear-gradient(90deg, rgba(122, 78, 23, 0.14) 0 1px, transparent 1px 18px),
    repeating-linear-gradient(0deg, rgba(122, 78, 23, 0.14) 0 1px, transparent 1px 18px),
    radial-gradient(ellipse at 30% 40%, #e9e4d6, #cfd3cf 85%) !important;
}
/* the scene is a plate in the almanac: crop marks, a vignette to the night, and the margin graticule along its head */
[data-chat-mode="game"] {
  position: relative;
}
[data-chat-mode="game"]::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  border: 14px solid transparent;
  border-image: url("theme:crop-night.svg") 24 / 14px / 0 stretch;
  background:
    url("theme:grat-night.svg") 0 0 / 48px 7px repeat-x,
    radial-gradient(ellipse at 50% 45%, transparent 35%, rgba(4, 6, 10, 0.78) 100%),
    repeating-linear-gradient(90deg, rgba(226, 196, 135, 0.07) 0 1px, transparent 1px 96px),
    repeating-linear-gradient(0deg, rgba(226, 196, 135, 0.07) 0 1px, transparent 1px 96px),
    linear-gradient(rgba(9, 13, 24, 0.42), rgba(9, 13, 24, 0.42));
  background-origin: border-box;
  box-shadow: inset 0 0 0 1px var(--pc-rule-gold);
}
:root[data-theme="light"] [data-chat-mode="game"]::after {
  border-image-source: url("theme:crop-day.svg");
  background:
    url("theme:grat-day.svg") 0 0 / 48px 7px repeat-x,
    radial-gradient(ellipse at 50% 45%, transparent 50%, rgba(60, 56, 48, 0.35) 100%),
    repeating-linear-gradient(90deg, rgba(122, 78, 23, 0.08) 0 1px, transparent 1px 96px),
    repeating-linear-gradient(0deg, rgba(122, 78, 23, 0.08) 0 1px, transparent 1px 96px),
    linear-gradient(rgba(205, 203, 196, 0.42), rgba(205, 203, 196, 0.42));
  background-origin: border-box;
}

/* ============================ CHATS SIDEBAR: the catalogue ============================ */
[data-component="ChatSidebar"] {
  background:
    url("theme:eyes-night.svg") 50% calc(100% - 4.2rem) / 5.6rem auto no-repeat,
    var(--sidebar);
}
:root[data-theme="light"] [data-component="ChatSidebar"] {
  background:
    url("theme:eyes-day.svg") 50% calc(100% - 4.2rem) / 5.6rem auto no-repeat,
    var(--sidebar);
}
[data-chat-row] {
  border-radius: 0;
  border-bottom: 1px solid var(--ov-line);
}
[data-chat-row][data-selected="true"] {
  background: var(--pc-sheet-2);
  box-shadow: inset 2px 0 0 var(--pc-gold);
}
[data-chat-row] .rounded-lg {
  border-radius: 999px;
}
/* Library mode: the idol keeps watch at the foot of the panel */
[data-component="RightPanelDesktop"] {
  background:
    url("theme:creature-idol.webp") 50% calc(100% - 4.2rem) / auto 9rem no-repeat,
    var(--sidebar);
}

/* ============================ HOME: photographic plates ============================ */
/* the world already has its own stars; the app's Home starfield and its pastel shell stars add coloured
   points (the lavender .y2k-star-md sat in the open sky plate at 45%/50%), so they step aside */
.mari-home-browser-starfield,
.y2k-star,
.y2k-star-md,
.y2k-star-lg {
  display: none;
}
[data-mari-part="home-widget"] {
  border-radius: 0;
  box-shadow: 0 0 0 1px var(--mari-home-widget-border);
  position: relative;
}
/* the plate's registration crop marks: eight 2px bars on a pseudo-element. (A border-image did the same
   but cost ~300ms of janky frames on the phone Home tap in WebKit; plain gradients cost nothing.) */
[data-mari-part="home-widget"]::before {
  --c: var(--pc-gold);
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 3;
  background:
    linear-gradient(var(--c), var(--c)) left top / 11px 2px,
    linear-gradient(var(--c), var(--c)) left top / 2px 11px,
    linear-gradient(var(--c), var(--c)) right top / 11px 2px,
    linear-gradient(var(--c), var(--c)) right top / 2px 11px,
    linear-gradient(var(--c), var(--c)) left bottom / 11px 2px,
    linear-gradient(var(--c), var(--c)) left bottom / 2px 11px,
    linear-gradient(var(--c), var(--c)) right bottom / 11px 2px,
    linear-gradient(var(--c), var(--c)) right bottom / 2px 11px;
  background-repeat: no-repeat;
}
[data-mari-part="home-widget"] [data-mari-part="home-widget-eyebrow"] {
  letter-spacing: 0.16em;
}
[data-mari-part="home-widget"] [data-mari-part="home-widget-title"] {
  font-weight: 400;
}

/* one set of crop marks only: the app's focus frame on Recent would add a second ring 7px out */
[data-home-widget-id="recent"] [data-mari-part="home-widget"] {
  border-image: none !important;
}
/* on a laptop-width Home the Recent plate stops short so the moon has an open gap of sky beside it */
@media (min-width: 1280px) and (max-width: 1700px) {
  /* Recent ends on the column line of the plates below; the right column's top is an open plate of sky
     (crop marks and a graticule foot, no sheet) with the moon set in it */
  :root:not([data-chat-id]) [data-home-widget-id="recent"] {
    width: calc((100% - clamp(0.65rem, 0.8vw, 0.95rem)) / 2);  /* the feed grid's own gap */
  }
  :root:not([data-chat-id]) [data-home-widget-id="recent"]::before {
    --c: var(--pc-gold);
    content: "";
    position: absolute;
    top: 0;
    bottom: 0;
    left: calc(100% + clamp(0.65rem, 0.8vw, 0.95rem));
    width: 100%;
    pointer-events: none;
    background:
      linear-gradient(var(--c), var(--c)) left top / 11px 2px,
      linear-gradient(var(--c), var(--c)) left top / 2px 11px,
      linear-gradient(var(--c), var(--c)) right top / 11px 2px,
      linear-gradient(var(--c), var(--c)) right top / 2px 11px,
      linear-gradient(var(--c), var(--c)) left bottom / 11px 2px,
      linear-gradient(var(--c), var(--c)) left bottom / 2px 11px,
      linear-gradient(var(--c), var(--c)) right bottom / 11px 2px,
      linear-gradient(var(--c), var(--c)) right bottom / 2px 11px,
      url("theme:grat-night.svg") 0 calc(100% - 3px) / 48px 7px repeat-x;
    background-repeat: no-repeat, no-repeat, no-repeat, no-repeat, no-repeat, no-repeat, no-repeat, no-repeat, repeat-x;
    background-origin: border-box;
    /* this pseudo-element is the app's hover glow layer (opacity 0, z-index -1): take it over outright */
    opacity: 1 !important;
    z-index: 0 !important;
    filter: none !important;
    transform: none !important;
    box-shadow: none !important;
    border-radius: 0 !important;
    transition: none !important;
  }
  :root[data-theme="light"]:not([data-chat-id]) [data-home-widget-id="recent"]::before {
    background-image:
      linear-gradient(var(--c), var(--c)), linear-gradient(var(--c), var(--c)), linear-gradient(var(--c), var(--c)), linear-gradient(var(--c), var(--c)),
      linear-gradient(var(--c), var(--c)), linear-gradient(var(--c), var(--c)), linear-gradient(var(--c), var(--c)), linear-gradient(var(--c), var(--c)),
      url("theme:grat-day.svg");
  }
}

/* the creature peeks up over the bottom edge of the Recent plate, in its empty corner */
@media (min-width: 900px) {
  [data-home-widget-id="recent"] {
    position: relative;
  }
  [data-home-widget-id="recent"]::after {
    content: "";
    position: absolute;
    right: 1.5rem;
    bottom: 0;
    width: 7.5rem;
    height: 4rem;
    background: url("theme:creature-over.webp") center bottom / contain no-repeat;
    pointer-events: none;
  }
  :root[data-theme="light"] [data-home-widget-id="recent"]::after { background-image: url("theme:creature-over-day.webp"); }
}
/* narrow screens get their cat too: a small one over the Recent plate's corner (no new row) */
@media (max-width: 899px) {
  [data-home-widget-id="recent"] { position: relative; }
  [data-home-widget-id="recent"]::after {
    content: "";
    position: absolute;
    right: 0.9rem;
    bottom: 0;
    width: 5.4rem;
    height: 2.7rem;
    background: url("theme:creature-over-sm.webp") center bottom / contain no-repeat;
    pointer-events: none;
  }
  :root[data-theme="light"] [data-home-widget-id="recent"]::after { background-image: url("theme:creature-over-sm-day.webp"); }
}
/* round 6: at the foot of the phone Home the page leaves a calm stretch of sea, so the cult at its breakfast
   shows below the last plate (the backdrop is fixed; this is the end of the page, not a new row) */
@media (max-width: 760px) {
  :root:not([data-chat-id]) .mari-home-feed-shell { padding-bottom: 10rem; }
}
/* round 5: on a phone Recent's foot is below the first screen, so the cat peers over its top edge instead,
   paws on the plate, in the empty space right of the Professor and Widgets buttons */
@media (max-width: 760px) {
  [data-home-widget-id="recent"]::after {
    bottom: auto;
    top: calc(-2.4rem + 3px);
    right: 1.5rem;
    width: 4.8rem;
    height: 2.4rem;
    z-index: 1;
  }
}

/* Home's mode chips and hero buttons: solid square plates, readable over the moon */
.ov-home-modes > button,
.ov-home-hero-actions > button,
.mari-chrome-control {
  border-radius: 2px !important;
}
.ov-home-modes > button,
.ov-home-hero-actions > button {
  background: var(--pc-sheet) !important;  /* the app paints these chips transparent; text over art needs a plate */
  border: 1px solid var(--pc-rule);
  color: var(--pc-ink);
}
[data-mari-part="home-art"] {
  display: none;
}
/* recent-chat thumbnails are moons like every other avatar */
.ov-recent__avatar,
.ov-recent__avatar img {
  border-radius: 999px !important;
}
.ov-recent__avatar {
  overflow: hidden;
}
/* the mode tags on Recent rows are square like every other chip */
.ov-recent__mode {
  border-radius: 0 !important;
}
/* the greeting and version sit over the moon: give them the almanac's title plate (no extra height) */
.mari-home-hero h1,
.mari-home-hero [class*="tracking-[0.14em]"] {
  width: fit-content;
  background: var(--pc-sheet);
  box-shadow: 0 0 0 1px var(--pc-rule);
  padding-inline: 0.4em;
}

/* one shape language: every pill-shaped control becomes a square plate (avatars stay round moons) */
.ov-btn,
button:not(:has(> img, > span > img)):not([role="switch"]):not([data-mari-part="avatar"] *),
:is(button, input, select, label, a)[class*="rounded-full"]:not(:has(> img)):not([role="switch"]),
:is(button, input, select, label, a)[class*="rounded-xl"],
:is(button, input, select, label)[class*="rounded-lg"],
div[class*="rounded-full"]:has(> input, > select, > button, > svg),
.ov-search,
.mari-chrome-field,
.ov-sideswitch,
.ov-select,
.ov-seg,
[class*="ov-gallery__view"],
[data-mari-part="card-art"],
.ov-card {
  border-radius: 2px !important;
}

/* ============================ DIALOGS AND WINDOWS: plates ============================ */
[role="dialog"],
.mari-window,
.mari-drawer {
  border-radius: 0;
  box-shadow: 0 0 0 1px var(--pc-rule);
}
[role="dialog"] h2,
.mari-window h2 {
  font-family: var(--mari-font-heading);
  font-weight: 400;
}

/* ============================ PAGES ============================ */
[data-mari-part="page"] {
  border-left: 3px double var(--pc-rule-gold);
}
/* the page floor thins toward the foot of the page so the cliff and the sea show through the empty lower half;
   checked against the brightest world pixel behind it: muted text stays >= 4.5:1 at 1194, 1440 and 1920, day and night */
:root[data-mari-app-backdrop] .mari-app [data-mari-part="page"]:not(.mari-mobile-detail-sheet) {
  background: linear-gradient(color-mix(in srgb, var(--pc-sheet) 90%, transparent), color-mix(in srgb, var(--pc-sheet) 90%, transparent) 30%, color-mix(in srgb, var(--pc-sheet) var(--pc-floor-foot), transparent)) !important;
}
:root[data-theme="dark"] { --pc-floor-foot: 70%; }
:root[data-theme="light"] { --pc-floor-foot: 78%; }
[data-mari-part="page-title"] {
  font-family: var(--mari-font-heading);
  font-weight: 400;
  letter-spacing: 0.01em;
}

/* ============================ HOVER (pointer devices only) ============================ */
@media (hover: hover) and (pointer: fine) {
  [data-chat-row]:hover {
    background: var(--ov-hover);
  }
  [data-mari-part="composer"] .mari-chat-send-btn:hover {
    filter: brightness(1.08);
  }
}
